#Class to improve test result reporting using a fluent API
#e.g.
#VerifyThat(si.getStatus()).equals("Ready to start").andReport("Status should be ready to start")

import time
import logging
import operator
import squishtest3 as sq
import testData

logger = logging.getLogger(__name__)

class VerifyThat:

    verification_count = 0
    screenshot_dir =""

    #def __init__(self, objUnderTest, screenshot=False, webdriver_obj=None):
    def __init__(self, objUnderTest, screenshot=False):
        self.obj = objUnderTest
        self.frames = 0
        self.screenshot = screenshot
        #self.webdriver = webdriver_obj

    @staticmethod
    def setScreenshotPath(path):
        VerifyThat.screenshot_dir =path

    def matches_testdata(self,testdata_row,testdata_field):
        '''
        attempts to verify actual result against expected result in test datasheet
        skips if expected result is not specified
        args:
            testdata_row(object)
            testdata_field(str)
        '''
        try:
            expected = str(testData.field(testdata_row,testdata_field))
            if  expected != "":
                self.expected = expected
                self.expr_str = "equals"
            else:
                self.expr_str = " not set "
                self.expected = self.obj
                sq.test.log("expected " + testdata_field + self.expr_str) #type:ignore
        except Exception as e:
            self.expr_str = " not in datasheet "
            self.expected = self.obj
            sq.test.log("expected " + testdata_field + self.expr_str) #type:ignore

        self.expr = operator.eq
        self.frames +=1
        return self

    def testdata_in_list(self,testdata_row,testdata_field):
        '''
        attempts to verify expected result in test datasheet appears in a list
        skips if expected result is not specified
        args:
            testdata_row(object)
            testdata_field(str)
        '''
        try:
            # removed str() as testData.field returns a string
            # testdata now changed to handle lists and split on ';'
            self.expected = testData.field(testdata_row,testdata_field).split(";")
            self.expr_str = "contains"

        except Exception as e:
            self.expr_str = " not in datasheet "
            self.expected = ""
            sq.test.log("expected " + testdata_field + self.expr_str) #type:ignore

        self.expr = VerifyThat._list_item_contains
        self.frames +=1
        return self

    def list_in_list(self,list):
        '''
        attempts to verify expected list appears in a list
        skips if expected result is not specified
        args:
            list=[]
        '''
        try:
            self.expected = list
            self.expr_str = "contains"

        except Exception as e:
            self.expr_str = " not in list "
            self.expected = ""
            sq.test.log("expected " + list + self.expr_str) #type:ignore

        self.expr = VerifyThat._list_item_contains
        self.frames +=1
        return self

    def not_list_in_list(self,list):
        '''
        attempts to verify expected list does not appears in a list
        skips if expected result is not specified
        args:
            list=[]
        '''
        try:
            self.expected = list
            self.expr_str = "contains"

        except Exception as e:
            self.expr_str = " not in list "
            self.expected = ""
            sq.test.log("expected " + list + self.expr_str) #type:ignore

        self.expr = VerifyThat._list_item_excludes
        self.frames +=1
        return self

    def equals(self, expected):
        self.expected = expected
        self.expr = operator.eq
        self.expr_str = "equals"
        self.frames +=1
        return self

    def notEquals(self, expected):
        self.expected = expected
        self.expr = operator.ne
        self.expr_str = "not equals"
        self.frames +=1
        return self

    def lessThan(self,expected):
        self.expected = expected
        self.expr=operator.lt
        self.expr_str= "less than"
        self.frames +=1
        return self

    def lessThanOrEqual(self,expected):
        self.expected = expected
        self.expr=operator.le
        self.expr_str= "less than or equal"
        self.frames +=1
        return self

    def greaterThan(self,expected):
        self.expected = expected
        self.expr=operator.gt
        self.expr_str= "greater than"
        self.frames +=1
        return self

    def greaterThanOrEqual(self,expected):
        self.expected = expected
        self.expr=operator.ge
        self.expr_str= "greater than or equal"
        self.frames +=1
        return self

    def isInstanceOf(self, expected_class):
        self.expected = expected_class
        self.expr = VerifyThat._obj_is_instance_of
        self.expr_str = "object is an instance of class"
        self.frames +=1
        return self

    def matches(self, expected_pattern):
#
#         Verify that a string has a given regex pattern.
#         e.g  pattern = "[a-z]+"
#              expected = "13245ahjfe6798.,[]&()*&)&^%&*$"
#              VerifyThat(target).matches(pattern).andReport("Regex search")
#
        self.expected = expected_pattern
        self.expr = VerifyThat._search_pattern
        self.expr_str = "matches"
        self.frames +=1
        return self


    @staticmethod  #?WHY
    def _search_pattern(test_string,pattern):
        import re
        p = re.compile(pattern)
        m = p.search(test_string)
        if m == None:
            logger.debug('No match for ' + pattern + ' in ' + test_string)
            return False
        else:
            logger.debug('Match found for ' + pattern + ' in ' + test_string + ' :: ' + str(m.group()))
            return True

    @staticmethod
    def _list_item_contains(list,search_for):
        '''searches for a string in each item of a list'''
        #Updated to work with list in list

        for each_item in search_for:
            item_in_list = False
            for list_item in list:

                if each_item in list_item:
                    item_in_list = True
                    break
                else:
                    item_in_list=False
                    sq.test.log("Following items not in list in _list_item_contians() "+str(each_item)+" not in "+str(list_item)) #type:ignore

            return item_in_list

    @staticmethod
    def _list_item_excludes(list,search_for):
        #Returns true if string is not present in list
        for each_item in search_for:
            item_in_list = False
            for list_item in list:
                if each_item in list_item:
                    item_in_list = False
                    break
                else:
                    item_in_list=True
                    sq.test.log("Following items not in list in _list_item_contians() "+str(each_item)+" not in "+str(list_item)) #type:ignore

            return item_in_list

    @staticmethod
    def _obj_is_instance_of(test_obj, some_class):
        try:
            if not isinstance(test_obj, some_class):
                logger.debug("Object is not an instance of class " + some_class.__name__)
                return False
        except TypeError:
            raise TypeError('given arg must be a class')
        return True


    def contains(self, expected_item):
        #TODO: check if string or list or set contains item
        #operator.contains(a, b)
        self.expected = expected_item
        self.expr = operator.__contains__
        self.expr_str = "contains"
        self.frames +=1
        return self


    def andReport(self, msg):
        self.verify (msg)
        self.frames +=1
        return self


    def andReportCritical(self, msg):

#         Terminates the whole test via Squish script exception if Fail.

        sq.testSettings.throwOnFailure = True
        sq.test.log("andReportCritical onEntry squish.testSettings.throwOnFailure is set as "+str(sq.testSettings.throwOnFailure)) #type:ignore
        self.verify (msg)
        self.frames +=1
        sq.testSettings.throwOnFailure = False
        sq.test.log("andReportCritical onExit squish.testSettings.throwOnFailure is set as "+str(sq.testSettings.throwOnFailure)) #type:ignore
        return self

    #ToT=Yes
    def verify(self, msg):
        self.__class__.verification_count +=1
        prefix = "(" + str(self.__class__.verification_count) + ") "
        self.frames +=1
        if self.screenshot: self.take_Step_Screenshot()
        sq.test.fixateResultContext(self.frames); #type:ignore
        prefixed_msg = prefix +  msg
        detail = str(self.obj) + " [" + self.expr_str + "] " + str(self.expected)

        if self.expr(self.obj, self.expected):
            #Output msg and detail to squish test reporter
            logger.info(prefixed_msg + "::" + detail + " PASSED.")
            sq.test.passes(prefixed_msg, detail + " PASSED.") #type:ignore
        else:
            logger.info(prefixed_msg + "::" + detail + " FAILED.")
            sq.test.fail(prefixed_msg, detail + " FAILED.") #type:ignore
        sq.test.restoreResultContext(); #type:ignore


    def take_Step_Screenshot(self):
        """
        Adds verification step number prefix to screenshot filename.
        """
        prefix = "step" + str(self.__class__.verification_count)
        self.__class__.takeScreenshot(prefix)


    @staticmethod
    def takeScreenshot(file_prefix):
        """
        Takes a screenshot and saves timestamped file to user defined directory if
        provided (see setScreenshotPath function) or to the test results directory.
        """

        file_prefix = VerifyThat.replaceIllegalChars(file_prefix)

        date_time = time.strftime("%d%m%Y-%H%M%S%p")
        directory = VerifyThat.screenshot_dir if (len(VerifyThat.screenshot_dir) >0 ) else sq.squishinfo.resultDir
        testcase_name = directory + "\\" + sq.squishinfo.testCase.split("\\")[-1]
        filename = testcase_name + "_" + file_prefix + "_" + date_time + ".png"
        logger.info("Saving screenshot at : " + filename)
        sq.saveDesktopScreenshot(filename)


    @staticmethod
    def replaceIllegalChars(path_string):
        illegal_chars = ['~','#','%','&','*','{','}','\\','/',':','<','>','?','+','|','"']
        cleansed = path_string
        for illegalchar in illegal_chars:
            if illegalchar in cleansed:
                cleansed = cleansed.replace(illegalchar, "_")

        return cleansed


class AbortTestCaseException(Exception):
    pass